using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args.Length > 0 ? args[0] : "../build.binlog";
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine($"Build Succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors
var errors = new List<(string project, string code, string message, string file, int line)>();
build.VisitAllChildren<Error>(error =>
{
    var project = "";
    var node = error.Parent;
    while (node != null)
    {
        if (node is Project p)
        {
            project = p.Name;
            break;
        }
        node = node.Parent;
    }
    errors.Add((project, error.Code ?? "", error.Text ?? error.ToString(), error.File ?? "", error.LineNumber));
});

// Collect all warnings
var warnings = new List<(string project, string code, string message)>();
build.VisitAllChildren<Warning>(warning =>
{
    var project = "";
    var node = warning.Parent;
    while (node != null)
    {
        if (node is Project p)
        {
            project = p.Name;
            break;
        }
        node = node.Parent;
    }
    warnings.Add((project, warning.Code ?? "", warning.Text ?? warning.ToString()));
});

Console.WriteLine($"=== ERRORS ({errors.Count} total) ===");
foreach (var group in errors.GroupBy(e => e.project))
{
    Console.WriteLine($"\n--- Project: {group.Key} ---");
    foreach (var e in group)
    {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
}

Console.WriteLine($"\n=== WARNINGS ({warnings.Count} total) ===");
foreach (var group in warnings.GroupBy(w => w.project))
{
    Console.WriteLine($"\n--- Project: {group.Key} ---");
    foreach (var w in group)
    {
        Console.WriteLine($"  [{w.code}] {w.message}");
    }
}

// Show project dependency tree / build order
Console.WriteLine("\n=== PROJECT BUILD ORDER ===");
build.VisitAllChildren<Project>(p =>
{
    Console.WriteLine($"  {p.Name} -> Succeeded: {p.Succeeded}");
});
