using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args.Length > 0 ? args[0] : "../build.binlog";
var build = BinaryLog.ReadBuild(binlogPath);

// Get source file contents embedded in binlog
Console.WriteLine("=== SEARCHING FOR SOURCE CONTENT AND PROJECT REFERENCES ===");
build.VisitAllChildren<Microsoft.Build.Logging.StructuredLogger.Item>(item =>
{
    if (item.Name == "ProjectReference" || item.Name == "PackageReference")
    {
        var project = "";
        var node = item.Parent;
        while (node != null)
        {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        Console.WriteLine($"  [{project}] {item.Name}: {item.Text}");
    }
});

// Show messages that might contain useful context
Console.WriteLine("\n=== RELEVANT MESSAGES ===");
build.VisitAllChildren<Message>(msg =>
{
    var text = msg.Text ?? "";
    if (text.Contains("error") || text.Contains("Newtonsoft") || text.Contains("PackageReference") || text.Contains("could not be"))
    {
        var project = "";
        var node = msg.Parent;
        while (node != null)
        {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        Console.WriteLine($"  [{project}] {text.Substring(0, Math.Min(text.Length, 200))}");
    }
});

// Check for Api build failures that might be cascading
Console.WriteLine("\n=== CHECKING FOR CASCADING FAILURES ===");
build.VisitAllChildren<Error>(error =>
{
    var project = "";
    var node = error.Parent;
    while (node != null)
    {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    Console.WriteLine($"  [{project}] {error.Code}: {error.Text}");
});
