cat > /tmp/sv-2eb5307705064289b8979fd24b4a4ff0/binlog-reader/Program.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args.Length > 0 ? args[0] : "../build.binlog";
var build = BinaryLog.ReadBuild(binlogPath);

// Get full item details with metadata
Console.WriteLine("=== PACKAGE REFERENCES WITH DETAILS ===");
build.VisitAllChildren<Microsoft.Build.Logging.StructuredLogger.Item>(item =>
{
    if (item.Name == "PackageReference")
    {
        var project = "";
        var node = item.Parent;
        while (node != null)
        {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        // Get folder/target context
        var folder = item.Parent?.ToString() ?? "?";
        Console.WriteLine($"  [{project}] PackageReference: {item.Text} (parent: {folder})");
        if (item is TreeNode tn)
        {
            foreach (var child in tn.Children)
                Console.WriteLine($"    metadata: {child}");
        }
    }
});

// Get project references
Console.WriteLine("\n=== PROJECT REFERENCES ===");
build.VisitAllChildren<Microsoft.Build.Logging.StructuredLogger.Item>(item =>
{
    if (item.Name == "ProjectReference")
    {
        var project = "";
        var node = item.Parent;
        while (node != null)
        {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        Console.WriteLine($"  [{project}] ProjectReference: {item.Text}");
    }
});

// Look for restore-related info
Console.WriteLine("\n=== NUGET RESTORE DETAILS ===");
build.VisitAllChildren<Message>(msg =>
{
    var text = msg.Text ?? "";
    if (text.Contains("Newtonsoft") || text.Contains("packages.config") || 
        text.Contains("PackageReference") || text.Contains("Restoring") ||
        text.Contains("Nothing to do") || text.Contains("restore"))
    {
        var project = "";
        var node = msg.Parent;
        while (node != null)
        {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        if (!text.Contains("Assembly loaded"))
            Console.WriteLine($"  [{project}] {text.Substring(0, Math.Min(text.Length, 300))}");
    }
});

// Dump the source file content from the binlog if available
Console.WriteLine("\n=== LOOKING FOR EMBEDDED FILES ===");
var archives = new List<ArchiveFile>();
build.VisitAllChildren<ArchiveFile>(f => archives.Add(f));
Console.WriteLine($"Found {archives.Count} embedded files");
foreach (var f in archives)
{
    Console.WriteLine($"  File: {f.Name} ({f.ToString().Length} chars)");
}
